package org.springframework.samples.petclinic.rest.validation;

/**
 * Thrown when an owner's e-mail address is present but not a syntactically valid
 * address. Handled by the REST {@code ExceptionControllerAdvice}, which translates
 * it into a {@code 400 Bad Request} response.
 */
public class InvalidEmailException extends RuntimeException {

    public InvalidEmailException(String message) {
        super(message);
    }
}

