35	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
36	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
37	import org.springframework.samples.petclinic.rest.validation.InvalidAddressException;
38	import org.springframework.samples.petclinic.rest.validation.InvalidEmailException;
39	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
40	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
41	import org.springframework.security.access.AccessDeniedException;
42	import org.springframework.validation.BindingResult;
43	import org.springframework.web.bind.MethodArgumentNotValidException;
44	import org.springframework.web.bind.annotation.ControllerAdvice;
45	import org.springframework.web.bind.annotation.ExceptionHandler;
46	import org.springframework.web.bind.annotation.ResponseBody;
47	
48	/**
49	 * Global Exception handler for REST controllers.
50	 * <p>
51	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
52	 *
53	 * @author Vitaliy Fedoriv
54	 * @author Alexander Dudkin
55	 */
56	@ControllerAdvice
57	public class ExceptionControllerAdvice {
58	
59	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
60	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
61	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
62	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
63	
64	    /**
65	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
66	     * class.
67	     *
68	     * @param e     Object referring to the thrown exception.
69	     * @param status HTTP response status.
70	     * @param url URL request.
71	     */
72	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
73	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
74	        problemDetail.setType(URI.create(url.toString()));
75	        problemDetail.setTitle(e.getClass().getSimpleName());
76	        problemDetail.setDetail(detail);
77	        problemDetail.setProperty("timestamp", Instant.now());
78	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
79	        return problemDetail;
80	    }
81	
82	    /**
83	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
84	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
85	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
86	     * would catch it and report an authorization failure as a 500.
87	     *
88	     * @param e The {@link AccessDeniedException} to propagate
89	     * @throws AccessDeniedException always
90	     */
91	    @ExceptionHandler(AccessDeniedException.class)
92	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
93	        throw e;
94	    }
95	
96	    /**
97	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
98	     *
99	     * @param e The {@link Exception} to be handled
100	     * @param request {@link HttpServletRequest} object referring to the current request.
101	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
102	     */
103	    @ExceptionHandler(Exception.class)
104	    @ResponseBody
105	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
106	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
107	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
108	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
109	        return ResponseEntity.status(status).body(detail);
110	    }
111	
112	    /**
113	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
114	     * method returns a 404 Not Found status if an entity does not exist.
115	     *
116	     * @param e The {@link DataIntegrityViolationException} to be handled
117	     * @param request {@link HttpServletRequest} object referring to the current request.
118	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
119	     */
120	    @ExceptionHandler(DataIntegrityViolationException.class)
121	    @ResponseBody
122	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
123	        logger.warn("Data integrity violation at {} {}: {}",
124	            request.getMethod(),
125	            request.getRequestURI(),
126	            e.getMessage());
127	        logger.debug("Data integrity violation stacktrace", e);
128	        HttpStatus status = HttpStatus.NOT_FOUND;
129	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
130	        return ResponseEntity.status(status).body(detail);
131	    }
132	
133	    /**
134	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not contain
135	     * exactly ten digits after non-digit characters are stripped, returning a 400 Bad Request status.
136	     *
137	     * @param e The {@link InvalidTelephoneException} to be handled
138	     * @param request {@link HttpServletRequest} object referring to the current request.
139	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
140	     */
141	    @ExceptionHandler(InvalidTelephoneException.class)
142	    @ResponseBody
143	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
144	        logger.warn("Invalid telephone at {} {}: {}",
145	            request.getMethod(),
146	            request.getRequestURI(),
147	            e.getMessage());
148	        HttpStatus status = HttpStatus.BAD_REQUEST;
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
150	        return ResponseEntity.status(status).body(detail);
151	    }
152	
153	    /**
154	     * Handles {@link InvalidEmailException} raised when an owner's e-mail address is present
155	     * but is not a syntactically valid address, returning a 400 Bad Request status.
156	     *
157	     * @param e The {@link InvalidEmailException} to be handled
158	     * @param request {@link HttpServletRequest} object referring to the current request.
159	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
160	     */
161	    @ExceptionHandler(InvalidEmailException.class)
162	    @ResponseBody
163	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
164	        logger.warn("Invalid email at {} {}: {}",
165	            request.getMethod(),
166	            request.getRequestURI(),
167	            e.getMessage());
168	        HttpStatus status = HttpStatus.BAD_REQUEST;
169	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
170	        return ResponseEntity.status(status).body(detail);
171	    }
172	
173	    /**
174	     * Handles {@link InvalidAddressException} raised when an owner's postal address is blank
175	     * once normalized, returning a 400 Bad Request status.
176	     *
177	     * @param e The {@link InvalidAddressException} to be handled
178	     * @param request {@link HttpServletRequest} object referring to the current request.
179	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
180	     */
181	    @ExceptionHandler(InvalidAddressException.class)
182	    @ResponseBody
183	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
184	        logger.warn("Invalid address at {} {}: {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getMessage());
188	        HttpStatus status = HttpStatus.BAD_REQUEST;
189	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidPostcodeException} raised when an owner's supplied postcode is not a
195	     * 4-digit value, or is out of range for the region derived from the owner's city, returning a
196	     * 400 Bad Request status.
197	     *
198	     * @param e The {@link InvalidPostcodeException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
201	     */
202	    @ExceptionHandler(InvalidPostcodeException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
205	        logger.warn("Invalid postcode at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getMessage());
209	        HttpStatus status = HttpStatus.BAD_REQUEST;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles {@link DuplicateIdentityException} raised when an owner is created whose derived
216	     * {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId})
217	     * exactly matches that of an existing owner, returning a 409 Conflict status. This single key
218	     * consolidates the former separate telephone, e-mail and household duplicate checks.
219	     *
220	     * @param e The {@link DuplicateIdentityException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
223	     */
224	    @ExceptionHandler(DuplicateIdentityException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
227	        logger.warn("Duplicate identity at {} {}: {}",
228	            request.getMethod(),
229	            request.getRequestURI(),
230	            e.getMessage());
231	        HttpStatus status = HttpStatus.CONFLICT;
232	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
233	        return ResponseEntity.status(status).body(detail);
234	    }
235	
236	    /**
237	     * Handles {@link CityCapacityExceededException} raised when an owner is created in a city
238	     * that already contains 50 or more owners, returning a 409 Conflict status.
239	     *
240	     * @param e The {@link CityCapacityExceededException} to be handled
241	     * @param request {@link HttpServletRequest} object referring to the current request.
242	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
243	     */
244	    @ExceptionHandler(CityCapacityExceededException.class)
245	    @ResponseBody
246	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
247	        logger.warn("City at capacity at {} {}: {}",
248	            request.getMethod(),
249	            request.getRequestURI(),
250	            e.getMessage());
251	        HttpStatus status = HttpStatus.CONFLICT;
252	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
253	        return ResponseEntity.status(status).body(detail);
254	    }
255	
256	    /**
257	     * Handles {@link DailyOwnerLimitExceededException} raised when an owner is created after
258	     * 100 or more owners have already been created today (by {@code registrationDate}), returning
259	     * a 429 Too Many Requests status.
260	     *
261	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
262	     * @param request {@link HttpServletRequest} object referring to the current request.
263	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
264	     */
265	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
266	    @ResponseBody
267	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
268	        logger.warn("Daily owner limit reached at {} {}: {}",
269	            request.getMethod(),
270	            request.getRequestURI(),
271	            e.getMessage());
272	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
273	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
274	        return ResponseEntity.status(status).body(detail);
275	    }
276	
277	    /**
278	     * Handles {@link FutureRegistrationDateException} raised when an owner is created with a
279	     * supplied {@code registrationDate} that is later than the current server date, returning
280	     * a 400 Bad Request status.
281	     *
282	     * @param e The {@link FutureRegistrationDateException} to be handled
283	     * @param request {@link HttpServletRequest} object referring to the current request.
284	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
285	     */
286	    @ExceptionHandler(FutureRegistrationDateException.class)
287	    @ResponseBody
288	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
289	        logger.warn("Future registration date at {} {}: {}",
290	            request.getMethod(),
291	            request.getRequestURI(),
292	            e.getMessage());
293	        HttpStatus status = HttpStatus.BAD_REQUEST;
294	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
295	        return ResponseEntity.status(status).body(detail);
296	    }
297	
298	    /**
299	     * Handles exception thrown by Bean Validation on controller methods parameters
300	     *
301	     * @param e The {@link MethodArgumentNotValidException} to be handled
302	     * @param request {@link HttpServletRequest} object referring to the current request.
303	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
304	     */
305	    @ExceptionHandler(MethodArgumentNotValidException.class)
306	    @ResponseBody
307	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
308	        HttpStatus status = HttpStatus.BAD_REQUEST;
309	        BindingErrorsResponse errors = new BindingErrorsResponse();
310	        BindingResult bindingResult = e.getBindingResult();
311	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
312	        if (bindingResult.hasErrors()) {
313	            errors.addAllErrors(bindingResult);
314	            List<String> errorFields = bindingResult.getFieldErrors().stream()
315	                .map(fieldError -> fieldError.getField())
316	                .distinct()
317	                .toList();
318	            detail.setProperty("errors", errorFields);
319	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
320	                .map(fieldError -> {
321	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
322	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
323	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
324	                        fieldError.getField(),
325	                        defaultMessage,
326	                        rejectedValue);
327	                    return new ValidationMessageDto(message)
328	                        .putAdditionalProperty("field", fieldError.getField())
329	                        .putAdditionalProperty("rejectedValue", rejectedValue)
330	                        .putAdditionalProperty("defaultMessage", defaultMessage);
331	                })
332	                .toList();
333	            logger.debug("Validation error at {} {}: {}",
334	                request.getMethod(),
335	                request.getRequestURI(),
336	                bindingResult.getFieldErrors());
337	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
338	            return ResponseEntity.status(status).body(detail);
339	        }
340	        return ResponseEntity.status(status).body(detail);
341	    }
342	
343	}
